      v1: { rival: '네 칼은 우리 할머니 프라이팬보다 녹슬었다네,', good: '네 류트는 물뿌리개에 낀 고양이 소리라네.', flat: '우리 할머니도 참 좋은 분이시라네.', off: '네 노래는 별로고 모자도 못생겼어.' },
      v2: { rival: '내 무릎만 한 고블린에게서 도망쳤다며,', good: '세 살배기 성가대 꼬마한테도 노래로 졌다며.', flat: '고블린은 무섭지, 누가 봐도 그렇다며.', off: '거짓말이야, 그 고블린은 엄청 크고 무서웠어.' },
      v3: { rival: '네 말은 하도 느려 달팽이가 앞지르네,', good: '네 말은 졸린 두꺼비와 경주해서 졌다지.', flat: '내 말은 괜찮아, 짐을 잔뜩 싣지.', off: '내 말은 아주 빠르고 아주 예뻐.' },
      v4: { rival: '보리 냄새만 맡아도 너는 뻗어 버리지,', good: '외상 술이 하도 많아 주인이 네 모자를 맡아 두었지.', flat: '보리는 참 좋지, 더는 말 안 하지.', off: '나는 많이 마셔, 여기 다들 알아.' },
      v5: { rival: '네 방패엔 곰팡이 치즈보다 구멍이 많구나,', good: '네 투구 속엔 황새가 둥지를 틀었구나.', flat: '나는 치즈가 좋아, 완두콩도 좋구나.', off: '내 방패는 새것이야, 지난주에 샀어.' },
      v6: { rival: '네가 노래하면 늑대들이 달에게 평화를 빌고,', good: '네가 노래하면 사제마저 노래가 끝나길 빌고.', flat: '늑대는 영리하지, 털도 북슬북슬하고.', off: '나 노래 잘해, 우리 엄마가 늘 그래.' },
      v7: { rival: '네 갑옷은 아무도 안 닦은 냄비처럼 번쩍이네,', good: '네 갑옷은 하도 삐걱대서 귀뚜라미도 외면하네.', flat: '냄비도 닦으면 번쩍이네.', off: '내 갑옷은 좋은 강철이고 매일 닦아.' },
      v8: { rival: '용을 잡았다더니 그 용은 연이었다지,', good: '너는 쏘지도 않을 벌 한 마리에 도망쳤다지.', flat: '연은 바람 좋을 때 날리면 재밌다지.', off: '진짜 용이었어, 날개도 다 있었다고.' },
      v9: { rival: '네 수염은 갓 깬 병아리 솜털처럼 가늘구나,', good: '네 수염엔 생쥐 둘, 부엉이 하나, 촛대 반쪽이 숨었구나.', flat: '병아리는 작고 꽤 빠르구나.', off: '내 수염은 멋있고 매일 아침 빗어.' },
      v10: { rival: '너는 하도 가난해 외투 단추로 술값을 내지,', good: '너는 약속 하나와 음 이탈 한 소절로 술값을 내지.', flat: '단추는 외투 여밀 때 참 쓸모 있지.', off: '나는 집에 금을 잔뜩 숨겨 놨어.' },
