    harvest: { name: '비옥한 비', desc: '작물이 50% 빨리 자라고 밭마다 수확이 하나 더.',
      lore: '빵 냄새가 나는 따뜻한 비. 늙은 농부들이 모자를 벗어 인사해요.' },
    chest: { name: '잃어버린 상자', desc: '골드, 별가루, 그리고 가끔 유물이 든 버려진 상자.',
      lore: '반쯤 묻혀 있고, 자물쇠는 오래전에 녹슬었어요. 두고 간 사람은 몹시 서둘렀나 봐요.' },
    aurora: { name: '옛사람들의 오로라', desc: '채집에서 두 배가 훨씬 자주 나오고, 숙련이 50% 빨리 올라요.',
      lore: '초록 불꽃이 봉우리 위로 굽이쳐요. 그 빛 아래서 모든 광맥과 물고기가 모습을 드러내요.' },
    merchant: { name: '베일의 대상', desc: '왕국의 어느 상점에도 없는 것을 골드나 별가루에 파는 대상.',
      lore: '아무도 오는 것을 보지 못해요. 비단 천막, 가면 쓴 상인, 있어서는 안 될 물건들.' },
    gilded_goblin: { name: '황금 고블린', desc: '금으로 뒤덮인 고블린이 왕국을 가로질러 달려요. 사라지기 전에 잡으세요.',
      lore: '웃고, 짤랑거리고, 아주 빨라요. 전설에 따르면 2분 넘게 머무르는 법이 없대요.' },
    blood_moon: { name: '핏빛 달', desc: '몬스터가 30% 강해지지만, 전리품이 두 배가 되고 희귀 전리품 확률이 세 배가 돼요.',
      lore: '달이 붉어지고 짐승들이 잠들지 않아요. 용감한 사냥꾼은 부자가 되고, 나머지는 돌아오지 못해요.' },
    eclipse: { name: '비전 일식', desc: '마법 피해 +50%, 룬 절반 보존, 룬 제작과 마법이 더 빨리 늘어요.',
      lore: '해가 검게 변하고 왕국의 모든 주문이 두 배로 밝게 타올라요.' },
    rift: { name: '떠도는 균열', desc: '세상의 찢어진 틈이 당신과 함께 강해지는 공포를 풀어놓아요. 그것은 유물을 지켜요.',
      lore: '공기가 낡은 천처럼 갈라져요. 반대편의 무언가가 기다려 왔어요.' },
    comet: { name: '소원의 혜성', desc: '경험치 +50%, 그리고 모든 행동과 싸움이 영구 소원을 줄 수 있어요.',
      lore: '평생 한 번이라고들 해요. 지나갈 때 소원을 속삭이면 하늘이 응답할지도 몰라요.' },
    eye: { name: '눈이 뜨이다', desc: '모든 것이 세 배: 경험치, 골드, 전리품, 그리고 더 빠른 행동. 그 시선은 그 자리에 있던 이들에게 선물을 남겨요.',
      lore: '별들이 멈춰요. 세상만큼 오래된 눈이 왕국 위에서 떠지고, 당신을 바라봐요.' },
