    goes: '동행',
    dismiss: '해고',
    sure: '영원히 해고할까요?',
    none: '아직 아무도 고용하지 않았어요.',
    recruits: '일자리를 찾는 사람들',
    hire: '고용 · {n}',
    hurt: '부상: {t}',
    hurtShort: '부상',
    away: '원정 중',
    noGold: '고용하려면 {n} 골드가 필요해요',
    cantPay: '동료들이 급료 {n} 골드를 원해요. 남아 있을 거예요',
    full: '{n}명만 동행할 수 있어요',
    regionHint: '동료는 지역의 생물을 뺀 모든 곳에 함께해요. 누가 갈지는 준비에서 고르세요.', partyWaits: '지역의 생물과는 동료 없이 싸워요. 동료는 보스, 던전, 탑, 그 밖의 모든 싸움에 함께해요.', partyWaitsShort: '대기 중: 지역 밖 모든 곳에서 싸워요',
    empty: '동행할 사람이 정해지지 않았어요. 준비에서 동료를 고용하세요.',
    met: '길에서 만남', join: '합류',
    uniques: {
      maelis: { name: '마엘리스', title: '늪의 마녀', bio: '개구리들이 기억하는 것보다 오래 썩은 늪에서 약을 달여 왔어요. 늪이 깨어났을 때 그 소리를 들은 사람이 그녀였고, 그 뒤로 듣기를 멈추지 않았어요.', hint: '이야기의 2막이 이끄는 썩은 늪 깊은 곳에서 기다려요.', reward: '그녀의 주문은 회복을 네 배로 깨뜨려요', trip: '마엘리스는 늪을 지나는 마른 길을 모두 알고 있었어요.' },
      hollis: { name: '홀리스', title: '부서진 방패', bio: '무덤이 빈 채로 발견될 때까지 옛 왕들의 잊힌 지하묘지를 지켰어요. 그날 밤 방패에 금이 갔지만, 지키지 못한 것을 잊지 않으려고 계속 들고 다녀요.', hint: '이야기 3막에서 찾게 될 무덤을 지키고 있어요.', reward: '고친 방패가 모든 강한 일격을 더 많이 받아 내요', trip: '홀리스가 전에 걸어 본 굴로 원정대를 이끌었어요.' },
      seren: { name: '세렌', title: '북방의 파수꾼', bio: '얼어붙은 봉우리의 마지막 파수꾼. 폭풍과 그 속을 걷는 것들을 세고, 두 번 빗나가는 법이 없어요.', hint: '4막의 얼어붙은 봉우리 높은 곳에서 북방 파수대를 지켜요.', reward: '기술을 열에 아홉은 끊어요', trip: '세렌이 봉우리의 바람을 읽고 고갯길을 찾았어요.' },
      ardan: { name: '아르단', title: '균열의 순례자', bio: '세상의 상처를 위해 기도하러 그 안으로 걸어 들어갔고, 믿음은 온전히, 머리는 하얗게 된 채로 걸어 나왔어요.', hint: '이야기의 마지막 막, 공허의 문 너머를 떠돌아요.', reward: '더 많이 치료하고 상태 이상을 더 빨리 풀어요', trip: '아르단은 용들이 어디서 자는지, 어디를 밟지 말아야 하는지 알았어요.' },
      vela: { name: '벨라', title: '길드 요원', bio: '길드는 질문이 환영받지 않는 곳에 그녀를 보내요. 길드의 신뢰를 얻은 사람에게 응하고, 지금은 그게 당신이에요.', hint: '길드 사건을 열 건 해결하면 합류해요.', reward: '그녀의 공격이 더 세게 들어가요', trip: '벨라는 지도를 그린 사람보다 지도를 더 잘 읽었어요.' },
    },
